CREATE TABLE public.workspace_email_auto_join (
  workspace_id uuid PRIMARY KEY REFERENCES public.workspaces(id) ON DELETE CASCADE,
  domain text NOT NULL UNIQUE,
  enabled_by_user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.workspace_email_auto_join ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.workspace_email_auto_join FROM PUBLIC, anon, authenticated;
GRANT ALL ON TABLE public.workspace_email_auto_join TO service_role;

CREATE FUNCTION private.email_auto_join_domain(p_user_id uuid)
RETURNS text
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_domain text;
  v_parent text;
BEGIN
  SELECT lower(split_part(actor.email, '@', 2)) INTO v_domain
  FROM auth.users AS actor
  WHERE actor.id = p_user_id
    AND actor.email_confirmed_at IS NOT NULL
    AND NOT COALESCE(actor.is_anonymous, false);

  IF v_domain IS NULL OR length(v_domain) > 253
    OR v_domain !~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$'
  THEN
    RETURN NULL;
  END IF;

  -- Provider subdomains (including private relay and per-user aliases) are public too.
  v_parent := v_domain;
  LOOP
    IF EXISTS (SELECT 1 FROM private.public_email_domains WHERE domain = v_parent) THEN
      RETURN NULL;
    END IF;
    EXIT WHEN position('.' in v_parent) = 0;
    v_parent := substring(v_parent FROM position('.' in v_parent) + 1);
  END LOOP;
  RETURN v_domain;
END;
$$;
REVOKE ALL ON FUNCTION private.email_auto_join_domain(uuid) FROM PUBLIC, anon, authenticated;

CREATE FUNCTION public.get_workspace_email_auto_join(p_workspace_id uuid)
RETURNS TABLE (domain text, enabled boolean)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  PERFORM private.require_workspace_member(p_workspace_id);
  IF NOT EXISTS (
    SELECT 1 FROM public.workspaces
    WHERE id = p_workspace_id AND owner_user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'only the workspace owner can configure email auto-join' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY SELECT private.email_auto_join_domain(auth.uid()), EXISTS (
    SELECT 1 FROM public.workspace_email_auto_join WHERE workspace_id = p_workspace_id
  );
END;
$$;
REVOKE ALL ON FUNCTION public.get_workspace_email_auto_join(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.get_workspace_email_auto_join(uuid) TO authenticated;

CREATE FUNCTION public.set_workspace_email_auto_join(p_workspace_id uuid, p_enabled boolean)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_domain text;
BEGIN
  PERFORM private.require_workspace_member(p_workspace_id);
  PERFORM 1 FROM public.workspaces
  WHERE id = p_workspace_id AND owner_user_id = auth.uid()
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'only the workspace owner can configure email auto-join' USING ERRCODE = '42501';
  END IF;

  IF p_enabled IS NOT TRUE THEN
    DELETE FROM public.workspace_email_auto_join WHERE workspace_id = p_workspace_id;
    RETURN;
  END IF;

  PERFORM private.require_workspace_capability(p_workspace_id, 'team.manage_members');
  v_domain := private.email_auto_join_domain(auth.uid());
  IF v_domain IS NULL THEN
    RAISE EXCEPTION 'a verified work email is required for email auto-join' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.workspace_verified_domains
    WHERE domain = v_domain AND workspace_id <> p_workspace_id
  ) THEN
    RAISE EXCEPTION 'email domain is already used by another workspace' USING ERRCODE = '22023';
  END IF;

  BEGIN
    INSERT INTO public.workspace_email_auto_join (workspace_id, domain, enabled_by_user_id)
    VALUES (p_workspace_id, v_domain, auth.uid())
    ON CONFLICT (workspace_id) DO UPDATE
    SET domain = EXCLUDED.domain, enabled_by_user_id = EXCLUDED.enabled_by_user_id;
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'email domain is already used by another workspace' USING ERRCODE = '22023';
  END;
END;
$$;
REVOKE ALL ON FUNCTION public.set_workspace_email_auto_join(uuid, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.set_workspace_email_auto_join(uuid, boolean) TO authenticated;

CREATE FUNCTION private.auto_join_email_workspace()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_domain text := private.email_auto_join_domain(NEW.id);
  v_workspace_id uuid;
  v_usage record;
  v_has_invitation boolean;
BEGIN
  DELETE FROM public.workspace_email_auto_join
  WHERE enabled_by_user_id = NEW.id AND domain IS DISTINCT FROM v_domain;
  IF v_domain IS NULL THEN RETURN NEW; END IF;

  SELECT workspace_id INTO v_workspace_id
  FROM public.workspace_email_auto_join WHERE domain = v_domain;
  IF v_workspace_id IS NULL THEN RETURN NEW; END IF;

  -- Invitation acceptance and membership changes take this same lock.
  PERFORM 1 FROM public.workspaces WHERE id = v_workspace_id FOR UPDATE;
  IF NOT EXISTS (
    SELECT 1 FROM public.workspaces AS workspace
    JOIN public.workspace_email_auto_join AS joining ON joining.workspace_id = workspace.id
    WHERE workspace.id = v_workspace_id
      AND workspace.kind = 'shared' AND workspace.deleted_at IS NULL
      AND joining.domain = v_domain
      AND joining.enabled_by_user_id = workspace.owner_user_id
      AND private.email_auto_join_domain(workspace.owner_user_id) = v_domain
      AND private.workspace_has_capability(workspace.id, 'team.manage_members')
  ) OR EXISTS (
    -- A removed member must use an explicit invitation to rejoin.
    SELECT 1 FROM public.workspace_memberships
    WHERE workspace_id = v_workspace_id AND user_id = NEW.id
  ) OR EXISTS (
    SELECT 1 FROM public.workspace_verified_domains
    WHERE domain = v_domain AND workspace_id <> v_workspace_id
  ) THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_usage FROM private.workspace_seat_usage(v_workspace_id);
  SELECT EXISTS (
    SELECT 1 FROM public.workspace_invitations
    WHERE workspace_id = v_workspace_id AND invitee_email = lower(btrim(NEW.email))
      AND accepted_at IS NULL AND revoked_at IS NULL AND expires_at > now()
  ) INTO v_has_invitation;
  -- A full team must never prevent account creation or sign-in.
  IF v_usage.seat_limit IS NOT NULL
    AND v_usage.used_seats + (CASE WHEN v_has_invitation THEN 0 ELSE 1 END) > v_usage.seat_limit
  THEN RETURN NEW; END IF;

  INSERT INTO public.workspace_memberships (workspace_id, user_id, role)
  VALUES (v_workspace_id, NEW.id, 'member') ON CONFLICT DO NOTHING;
  UPDATE public.workspace_invitations
  SET accepted_at = now(), invitee_user_id = NEW.id, updated_at = now()
  WHERE workspace_id = v_workspace_id AND invitee_email = lower(btrim(NEW.email))
    AND accepted_at IS NULL AND revoked_at IS NULL AND expires_at > now();
  RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION private.auto_join_email_workspace() FROM PUBLIC, anon, authenticated;

CREATE TRIGGER on_auth_user_email_auto_join
AFTER INSERT OR UPDATE OF email, email_confirmed_at, is_anonymous, last_sign_in_at ON auth.users
FOR EACH ROW EXECUTE FUNCTION private.auto_join_email_workspace();

CREATE FUNCTION private.disable_email_auto_join_on_owner_change()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  DELETE FROM public.workspace_email_auto_join WHERE workspace_id = NEW.id;
  RETURN NEW;
END;
$$;
REVOKE ALL ON FUNCTION private.disable_email_auto_join_on_owner_change() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER on_workspace_owner_email_auto_join
AFTER UPDATE OF owner_user_id ON public.workspaces
FOR EACH ROW WHEN (OLD.owner_user_id IS DISTINCT FROM NEW.owner_user_id)
EXECUTE FUNCTION private.disable_email_auto_join_on_owner_change();

COMMIT;
